insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a1_0001', 'A1', 'My Morning', 'Every morning Maria wakes up at six o’clock. She opens the window and looks at the bright sky. Then she makes a cup of coffee and drinks it slowly. After that she reads a short book for ten minutes. Finally she puts on her shoes and walks to the bus stop. The bus arrives at seven fifteen. She enjoys the quiet time before work.', 64) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a1_0002', 'A1', 'Shopping List', 'Tom writes a shopping list on a piece of paper. He needs three apples, a loaf of bread, two cartons of milk, and a box of cereal. He goes to the store at ten o’clock. In the fruit section he picks the red apples. In the dairy aisle he chooses the fresh milk. He pays at the checkout and walks home. He feels happy with his purchases.', 67) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a1_0003', 'A1', 'At the Park', 'On Saturday morning Alex goes to the park near his house. The grass is green and the trees are tall. He sees a small squirrel running up a tree. He sits on a wooden bench to rest and watches the birds fly. A gentle wind blows and he feels calm. After an hour he stands up and walks back home. He enjoys the quiet afternoon.', 65) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a1_0004', 'A1', 'Anna''s Birthday', 'Anna celebrates her sixth birthday with family and friends. The living room is decorated with colorful balloons and a big banner. Her mother bakes a chocolate cake with pink frosting. Everyone sings the happy birthday song and Anna blows out the candles. She opens a gift box and finds a new doll inside. The party ends with laughter and games. She feels very special today.', 65) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a2_0005', 'A2', 'Saturday Market Trip', 'Last Saturday, Anna went to the local market with her brother. They arrived early because the stalls open at nine. Anna bought fresh strawberries, a loaf of bread, and some cheese. Her brother chose a pair of trainers and a blue scarf. After shopping, they sat on a bench and ate an apple each. The weather was sunny but a little windy. They left the market at half past eleven.', 70) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a2_0006', 'A2', 'First Pasta Attempt', 'Yesterday, Marco tried to make a simple pasta dish for the first time. He boiled water, added salt, and put the pasta in. While the pasta cooked, he chopped tomatoes, garlic, and basil. He mixed the vegetables with olive oil in a pan and stirred them for five minutes. When the pasta was ready, he drained it and combined everything in a large bowl. The meal smelled delicious, and Marco felt proud.', 72) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a2_0007', 'A2', 'Seaside Holiday Plans', 'Next month, the Patel family will travel to the seaside. They have booked a small hotel near the beach. Mr Patel wants to swim every morning, while Mrs Patel prefers to read on the sand. Their daughter, Priya, hopes to collect shells, and their son, Rohan, plans to try surfing. The family will leave early on Saturday and return the following Sunday. They are excited about the trip.', 68) on conflict (id) do nothing;
insert into lt_passages (id, cefr_tag, title, body, word_count) values ('ltp_a2_0008', 'A2', 'New Neighbour Lena', 'This morning, a new neighbour moved into the flat next to mine. Her name is Lena and she works as a graphic designer. She brought a large plant and a bright rug. We talked for a few minutes in the hallway. Lena said she likes quiet evenings and often reads before bed. I offered to help her with the heavy boxes, but she smiled and said she was fine.', 69) on conflict (id) do nothing;
