insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0038', 'listening', 'A1', -2.5, 'What does the speaker drink in the morning?', '["tea","coffee","juice","water"]'::jsonb, 1, null, null, 'Good morning. I wake up at seven o’clock. First I brush my teeth. Then I make a cup of coffee. I drink it while I read the news. After that I eat toast with jam. Then I go to work.', 'ai', false, 'draft') on conflict (id) do nothing;
insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0039', 'listening', 'A1', -2.5, 'How many apples does the customer buy?', '["three","five","two","four"]'::jsonb, 0, null, null, 'Excuse me, how much are the apples? They are one pound each. I would like three apples, please. Here you are. That is three pounds. Thank you. The apples look fresh and red. I will eat them for lunch.', 'ai', false, 'draft') on conflict (id) do nothing;
insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0040', 'listening', 'A1', -2.5, 'Where does the speaker go on Saturday?', '["cinema","library","park","beach"]'::jsonb, 2, null, null, 'On Saturday I usually go to the park. I walk there with my dog. We play with a ball. In the afternoon I read a book on a bench. Sunday I stay at home and relax.', 'ai', false, 'draft') on conflict (id) do nothing;
insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0041', 'listening', 'A1', -2.5, 'Which street is the museum on?', '["Main Street","High Street","Oak Street","Pine Street"]'::jsonb, 1, null, null, 'Excuse me, where is the museum? Go straight on this road. Turn left at the traffic lights. The museum is on High Street, next to the library. It opens at ten in the morning.', 'ai', false, 'draft') on conflict (id) do nothing;
insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0042', 'listening', 'A1', -2.5, 'What is the speaker''s favorite fruit?', '["banana","apple","orange","mango"]'::jsonb, 2, null, null, 'I like many fruits, but my favorite is the orange. It is sweet and juicy. I eat one every day for breakfast. Sometimes I make orange juice. It gives me lots of energy for the morning.', 'ai', false, 'draft') on conflict (id) do nothing;
insert into lt_items (id, type, cefr_tag, difficulty_b, stem, options, correct_index, passage_id, passage_order, audio_script, source, reviewed, status) values ('lt_a1_listening_0043', 'listening', 'A1', -2.5, 'What time does the English class start?', '["9:00","11:00","12:00","10:00"]'::jsonb, 3, null, null, 'Our English class is on Monday and Wednesday. It starts at ten o’clock and finishes at eleven thirty. The teacher is Mrs. Brown. We practice speaking and listening. We also do homework after every class.', 'ai', false, 'draft') on conflict (id) do nothing;
